 "content": "def transform(grid):
    """Extend full 3x3 solid-color blocks along their middle row and column.

    Where projections of different colors intersect, leave the intersection blank.
    """
    h, w = len(grid), len(grid[0])
    centers = {}
    for r in range(h - 2):
        for c in range(w - 2):
            color = grid[r][c]
            if color and all(grid[rr][cc] == color
                             for rr in range(r, r + 3)
                             for cc in range(c, c + 3)):
                centers[(r + 1, c + 1)] = color

    lines = {}
    for (r, c), color in centers.items():
        for x in range(w):
            lines.setdefault((r, x), set()).add(color)
        for y in range(h):
            lines.setdefault((y, c), set()).add(color)

    out = [row[:] for row in grid]
    for (r, c), colors in lines.items():
        out[r][c] = next(iter(colors)) if len(colors) == 1 else 0
    return out
